function rowToEntry(r){const q=r.type==="question";return{id:r.id,type:r.type,icon:q?"❓":"📝",title:titleOf(r.text||""),meta:(r.area?.name?r.area.name+" · ":"")+fmt(r.created_at)+(q?" · "+(r.question_status==="answered"?"Respondida":"Pendente"):""),text:r.text||"",area:r.area?.name||"",theme:r.theme?.name||"",person:r.person?.name||"",favorite:!!r.favorite,status:r.question_status,answer:r.answer||"",answeredBy:r.answer_person?.name||"",answeredAt:r.answered_at||null,created_at:r.created_at,updated_at:r.updated_at,procedure_id:r.procedure_id||null,area_id:r.area_id||null,theme_id:r.theme_id||null,person_id:r.person_id||null }}
async function loadTaxonomy(){
  if(!session)return;
  const [a,t,p]=await Promise.all([
    db.from("areas").select("id,name").eq("active",true).order("name"),
    db.from("themes").select("id,name,area_id").eq("active",true).order("name"),
    db.from("people").select("id,name").eq("active",true).order("name")
  ]);
  if(a.error)throw a.error;if(t.error)throw t.error;if(p.error)throw p.error;
  const uniqueByName=list=>{const seen=new Set();return (list||[]).filter(x=>{const key=(x.name||"").trim().toLocaleLowerCase("pt-PT");if(!key||seen.has(key))return false;seen.add(key);return true})};areas=uniqueByName(a.data);themes=uniqueByName(t.data);people=uniqueByName(p.data);
}
async function loadProcedures(){if(!session)return;const{data,error}=await db.from("procedures").select("*,area:areas(name),theme:themes(name),learning_history(level,created_at)").eq("active",true).order("created_at",{ascending:false});if(error){console.error(error);return}procedures=(data||[]).map(p=>{const history=(p.learning_history||[]).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));return{...p,history,level:history[history.length-1]?.level||""}})}
async function loadTags(){if(!session)return;const{data,error}=await db.from("tags").select("id,name").eq("user_id",session.user.id).order("name");if(error){console.error("loadTags",error);tags=[];return}tags=data||[]}
async function loadAttachmentIndicators(){if(!session)return;const{data,error}=await db.from("attachments").select("entry_id,procedure_id");if(error){console.error("loadAttachmentIndicators",error);return}attachmentEntryIds=new Set((data||[]).map(a=>a.entry_id).filter(Boolean).map(String));attachmentProcedureIds=new Set((data||[]).map(a=>a.procedure_id).filter(Boolean).map(String))}
async function loadEntries(){if(!session)return;const{data,error}=await db.from("entries").select("*").is("deleted_at",null).order("created_at",{ascending:false});if(error){console.error("loadEntries",error);entries=[];return}entries=(data||[]).map(r=>{const area=areas.find(x=>x.id===r.area_id),theme=themes.find(x=>x.id===r.theme_id),person=people.find(x=>x.id===r.person_id),answerPerson=people.find(x=>x.id===r.answered_by_id);return rowToEntry({...r,area:area?{name:area.name}:null,theme:theme?{name:theme.name}:null,person:person?{name:person.name}:null,answer_person:answerPerson?{name:answerPerson.name}:null})})}
function recoveryScreen(msg=""){document.querySelector("header").style.display="none";document.querySelector("nav").style.display="none";app.innerHTML='<div style="padding-top:18vh"><h1>🐾 Nova palavra-passe</h1><div class="muted">Escolhe a nova palavra-passe de acesso ao Caderno Veterinário.</div><div class="card"><div class="field"><label>Nova palavra-passe</label><input id="newPassword" type="password" autocomplete="new-password"></div><div class="field"><label>Confirmar palavra-passe</label><input id="confirmPassword" type="password" autocomplete="new-password"></div><button class="btn" id="recoveryBtn">Guardar nova palavra-passe</button><div id="recoveryMsg" class="muted small center-note">'+esc(msg)+'</div></div></div>';document.querySelector("#recoveryBtn").onclick=async()=>{const p=document.querySelector("#newPassword").value,q=document.querySelector("#confirmPassword").value,m=document.querySelector("#recoveryMsg"),b=document.querySelector("#recoveryBtn");if(p.length<6){m.textContent="A palavra-passe deve ter pelo menos 6 caracteres.";return}if(p!==q){m.textContent="As palavras-passe não coincidem.";return}b.disabled=true;m.textContent="A guardar…";const{error}=await db.auth.updateUser({password:p});if(error){console.error(error);m.textContent="Não foi possível alterar a palavra-passe. Pede um novo email de recuperação e tenta novamente.";b.disabled=false;return}history.replaceState({},document.title,location.pathname);alert("Palavra-passe alterada ✓");const{data}=await db.auth.getSession();session=data.session;document.querySelector("header").style.display="";document.querySelector("nav").style.display="";await Promise.all([loadTaxonomy(),loadProcedures(),loadTags()]);await loadEntries();await loadAttachmentIndicators();render()}}function loginScreen(msg=""){document.querySelector("header").style.display="none";document.querySelector("nav").style.display="none";app.innerHTML='<div style="padding-top:18vh"><h1>🐾 Caderno Veterinário</h1><div class="muted">Entra no teu caderno pessoal.</div><div class="card"><div class="field"><label>Email</label><input id="loginEmail" type="email" autocomplete="email"></div><div class="field"><label>Palavra-passe</label><input id="loginPassword" type="password" autocomplete="current-password"></div><button class="btn" id="loginBtn">Entrar</button><div id="loginMsg" class="muted small center-note">'+esc(msg)+'</div></div></div>';document.querySelector("#loginBtn").onclick=login}
async function login(){const b=document.querySelector("#loginBtn"),m=document.querySelector("#loginMsg");b.disabled=true;m.textContent="A entrar…";const{data,error}=await db.auth.signInWithPassword({email:document.querySelector("#loginEmail").value.trim(),password:document.querySelector("#loginPassword").value});if(error){m.textContent="Não foi possível entrar. Confirma o email e a palavra-passe.";b.disabled=false;return}session=data.session;document.querySelector("header").style.display="";document.querySelector("nav").style.display="";await Promise.all([loadTaxonomy(),loadProcedures(),loadTags()]);await loadEntries();await loadAttachmentIndicators();render()}
