  if(linked.length){openProcedureDeleteBlocked(id);return}
  sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div class="sheet-title">Apagar procedimento?</div><button class="close" id="x">×</button></div><div class="card"><div class="item-title">'+esc(p.title)+'</div><div class="muted small">O procedimento deixa de aparecer em Aprender, nas pesquisas e nos seletores. O histórico de aprendizagem fica preservado.</div></div><button class="btn delete-entry-btn" id="confirmDeleteProcedure">Sim, apagar procedimento</button><button class="btn secondary-btn" id="cancelDeleteProcedure">Cancelar</button><div class="muted small center-note" id="deleteProcedureMsg"></div></div>';
  document.querySelector("#x").onclick=()=>editProcedure(id);document.querySelector("#cancelDeleteProcedure").onclick=()=>editProcedure(id);
