async function uploadEntryAttachments(entryId,files){for(const file of files||[]){const safe=(file.name||"ficheiro").replace(/[^a-zA-Z0-9._-]+/g,"_"),path=session.user.id+"/entries/"+entryId+"/"+crypto.randomUUID()+"-"+safe;const{error:upErr}=await db.storage.from("attachments").upload(path,file,{contentType:file.type||"application/octet-stream",upsert:false});if(upErr)throw upErr;const{error:dbErr}=await db.from("attachments").insert({user_id:session.user.id,entry_id:entryId,file_name:file.name||safe,storage_path:path,mime_type:file.type||null,file_size:file.size||null});if(dbErr){await db.storage.from("attachments").remove([path]);throw dbErr}}}
