  sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div class="sheet-title">Nova '+t.toLowerCase()+'</div><button class="close" id="x">×</button></div><div class="field"><label>'+label+'</label><textarea id="txt" placeholder="Escreve aqui…" autofocus></textarea></div><details class="details"><summary>Adicionar detalhes</summary><div class="field"><label>Área</label><select id="area"><option value="">Sem área</option>'+areaOpts+'<option value="__new">＋ Nova área…</option></select></div><div id="newAreaBox"></div><div class="field"><label>Tema</label><select id="theme" disabled><option value="">Sem tema</option></select></div><div id="newThemeBox"></div><div class="field"><label>Pessoa</label><select id="person"><option value="">Sem pessoa</option>'+peopleOpts+'<option value="__new">＋ Nova pessoa…</option></select></div><div id="newPersonBox"></div><div class="field"><label>Procedimento</label><select id="procedure"><option value="">Sem procedimento</option>'+procedureOpts+'<option value="__new">＋ Novo procedimento…</option></select></div><div class="field"><label>🏷️ Tags</label><div id="tagChips" class="summary"></div><input id="tagInput" placeholder="Adicionar tag…" autocomplete="off"><div id="tagSuggestions"></div></div>'+attachmentPickerHtml()+'</details><button class="btn" id="save">Guardar</button><div id="saveMsg" class="muted small center-note">Data e hora são registadas automaticamente.</div></div>';
  document.querySelector("#x").onclick=close;
