function taxKey(v){return (v||"").trim().normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("pt-PT")}
async function existingArea(name){const key=taxKey(name),{data,error}=await db.from("areas").select("id,name,active").eq("user_id",session.user.id);if(error)throw error;return (data||[]).find(x=>taxKey(x.name)===key)}
async function existingTheme(name,areaId){const key=taxKey(name);let q=db.from("themes").select("id,name,area_id,active").eq("user_id",session.user.id).eq("area_id",areaId);const{data,error}=await q;if(error)throw error;return (data||[]).find(x=>taxKey(x.name)===key)}
async function existingPerson(name){const key=taxKey(name),{data,error}=await db.from("people").select("id,name,active").eq("user_id",session.user.id);if(error)throw error;return (data||[]).find(x=>taxKey(x.name)===key)}
async function reactivateTaxonomy(table,item){if(item&&!item.active){const{error}=await db.from(table).update({active:true}).eq("id",item.id);if(error)throw error}return item}
