function openOrganization(){sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div><div class="eyebrow">DEFINIÇÕES</div><div class="sheet-title">Organização do Caderno</div></div><button class="close" id="x">×</button></div><div class="muted">Gere os nomes que usas para organizar os teus registos.</div><div class="card"><button class="recent-item recent-button" data-manage="areas"><div class="item-icon">📁</div><div class="item-main"><div class="item-title">Áreas</div><div class="muted small">'+areas.length+' ativas</div></div><div class="chev">›</div></button><button class="recent-item recent-button" data-manage="themes"><div class="item-icon">🏷️</div><div class="item-main"><div class="item-title">Temas</div><div class="muted small">'+themes.length+' ativos</div></div><div class="chev">›</div></button><button class="recent-item recent-button" data-manage="people"><div class="item-icon">👤</div><div class="item-main"><div class="item-title">Pessoas</div><div class="muted small">'+people.length+' ativas</div></div><div class="chev">›</div></button><button class="recent-item recent-button" data-manage="tags"><div class="item-icon">🏷️</div><div class="item-main"><div class="item-title">Tags</div><div class="muted small">'+tags.length+' criadas</div></div><div class="chev">›</div></button></div></div>';document.querySelector("#x").onclick=openMenu;document.querySelectorAll("[data-manage]").forEach(b=>b.onclick=()=>b.dataset.manage==="tags"?openTagsManager():openTaxonomyManager(b.dataset.manage))}
function openTagsManager(){sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div><div class="eyebrow">ORGANIZAÇÃO</div><div class="sheet-title">Tags</div></div><button class="close" id="x">×</button></div><div class="muted">Gere as tags que usas para relacionar e encontrar informação.</div><div class="card">'+(tags.length?tags.map(t=>'<div class="recent-item"><div class="item-icon">🏷️</div><div class="item-main"><div class="item-title">'+esc(t.name)+'</div></div><button class="icon-btn" data-edit-tag="'+t.id+'">Editar</button></div>').join(""):'<div class="muted small">Ainda não existem tags.</div>')+'</div></div>';document.querySelector("#x").onclick=openOrganization;document.querySelectorAll("[data-edit-tag]").forEach(b=>b.onclick=()=>editManagedTag(b.dataset.editTag))}
function editManagedTag(id){const item=tags.find(t=>t.id===id);if(!item)return;sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div class="sheet-title">Editar tag</div><button class="close" id="x">×</button></div><div class="field"><label>Nome</label><input id="managedTagName" value="'+esc(item.name)+'"></div><button class="btn" id="managedTagSave">Guardar alterações</button><button class="btn secondary" id="managedTagDelete">Apagar</button><div class="muted small center-note" id="managedTagMsg"></div></div>';document.querySelector("#x").onclick=openTagsManager;document.querySelector("#managedTagSave").onclick=async()=>{const name=document.querySelector("#managedTagName").value.trim(),msg=document.querySelector("#managedTagMsg");if(!name)return;if(tags.some(t=>t.id!==id&&taxKey(t.name)===taxKey(name))){msg.textContent="Já existe uma tag com esse nome.";return}const{error}=await db.from("tags").update({name}).eq("id",id);if(error){msg.textContent="Erro: "+error.message;return}await loadTags();openTagsManager()};document.querySelector("#managedTagDelete").onclick=async()=>{const msg=document.querySelector("#managedTagMsg");msg.textContent="A verificar utilização…";try{const refs=await tagReferences(id);if(refs.entries.length||refs.procedures.length){openTagReferences(item,refs);return}if(!confirm("Apagar esta tag?")){msg.textContent="";return}const{error}=await db.from("tags").delete().eq("id",id);if(error)throw error;await loadTags();openTagsManager()}catch(err){msg.textContent="Erro: "+(err.message||"não foi possível verificar")}}}
async function tagReferences(id){const[e,p]=await Promise.all([db.from("entry_tags").select("entry_id").eq("tag_id",id),db.from("procedure_tags").select("procedure_id").eq("tag_id",id)]);if(e.error)throw e.error;if(p.error)throw p.error;return{entries:(e.data||[]).map(x=>x.entry_id),procedures:(p.data||[]).map(x=>x.procedure_id)}}
function openTagReferences(item,refs){const linkedEntries=[...new Set(refs.entries)].map(id=>entries.find(e=>String(e.id)===String(id))).filter(Boolean),linkedProcedures=[...new Set(refs.procedures)].map(id=>procedures.find(p=>String(p.id)===String(id))).filter(Boolean);const groups=[];if(linkedEntries.length)groups.push('<div class="eyebrow">CADERNO</div>'+linkedEntries.map(e=>'<button class="recent-item recent-button" data-tag-ref-entry="'+e.id+'"><div class="item-icon">'+e.icon+'</div><div class="item-main"><div class="item-title">'+esc(e.title)+'</div><div class="item-meta">'+esc(e.meta)+'</div></div><div class="chev">›</div></button>').join(""));if(linkedProcedures.length)groups.push('<div class="eyebrow">PROCEDIMENTOS</div>'+linkedProcedures.map(p=>'<button class="recent-item recent-button" data-tag-ref-procedure="'+p.id+'"><div class="item-icon">📚</div><div class="item-main"><div class="item-title">'+esc(p.title)+'</div></div><div class="chev">›</div></button>').join(""));sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div><div class="eyebrow">EM UTILIZAÇÃO</div><div class="sheet-title">Não é possível apagar</div></div><button class="close" id="x">×</button></div><div class="muted">“'+esc(item.name)+'” ainda está associada a estes registos. Abre-os diretamente aqui e retira ou altera a tag primeiro.</div><div class="card taxonomy-ref-list">'+groups.join("")+'</div></div>';document.querySelector("#x").onclick=()=>editManagedTag(item.id);document.querySelectorAll("[data-tag-ref-entry]").forEach(b=>b.onclick=()=>openEntry(b.dataset.tagRefEntry));document.querySelectorAll("[data-tag-ref-procedure]").forEach(b=>b.onclick=()=>openProcedure(b.dataset.tagRefProcedure))}
function openTaxonomyManager(kind){const cfg=kind==="areas"?{title:"Áreas",singular:"área",icon:"📁",list:areas,table:"areas"}:kind==="themes"?{title:"Temas",singular:"tema",icon:"🏷️",list:themes,table:"themes"}:{title:"Pessoas",singular:"pessoa",icon:"👤",list:people,table:"people"};sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div><div class="eyebrow">ORGANIZAÇÃO</div><div class="sheet-title">'+cfg.title+'</div></div><button class="close" id="x">×</button></div><button class="btn" id="taxonomyNew">＋ Nov'+(kind==="areas"?"a ":"o ")+cfg.singular+'</button><div class="card">'+(cfg.list.length?cfg.list.map(x=>'<div class="recent-item"><div class="item-icon">'+cfg.icon+'</div><div class="item-main"><div class="item-title">'+esc(x.name)+'</div>'+(kind==="themes"?'<div class="muted small">'+esc(areas.find(a=>a.id===x.area_id)?.name||"Sem área")+'</div>':'')+'</div><button class="icon-btn taxonomy-edit" data-tax-id="'+x.id+'">Editar</button></div>').join(""):'<div class="muted small">Ainda não existem registos.</div>')+'</div></div>';document.querySelector("#x").onclick=openOrganization;document.querySelector("#taxonomyNew").onclick=()=>newTaxonomy(kind);document.querySelectorAll(".taxonomy-edit").forEach(b=>b.onclick=()=>editTaxonomy(kind,b.dataset.taxId))}
function newTaxonomy(kind){const label=kind==="areas"?"área":kind==="themes"?"tema":"pessoa",title=kind==="areas"?"Nova área":kind==="themes"?"Novo tema":"Nova pessoa",areaField=kind==="themes"?'<div class="field"><label>Área</label><select id="newTaxArea"><option value="">Escolher área…</option>'+areas.map(a=>'<option value="'+a.id+'">'+esc(a.name)+'</option>').join("")+'</select></div>':"";sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div class="sheet-title">'+title+'</div><button class="close" id="x">×</button></div>'+areaField+'<div class="field"><label>Nome</label><input id="newTaxName" placeholder="Nome"></div><button class="btn" id="newTaxSave">Guardar</button><div class="muted small center-note" id="newTaxMsg"></div><div id="reactivateWrap"></div></div>';document.querySelector("#x").onclick=()=>openTaxonomyManager(kind);setTimeout(()=>document.querySelector(kind==="themes"?"#newTaxArea":"#newTaxName")?.focus(),50);document.querySelector("#newTaxSave").onclick=async()=>{const name=document.querySelector("#newTaxName").value.trim(),msg=document.querySelector("#newTaxMsg"),wrap=document.querySelector("#reactivateWrap"),saveBtn=document.querySelector("#newTaxSave");wrap.innerHTML="";saveBtn.style.display="";if(!name){msg.textContent="Escreve o nome.";return}try{let existing=null,payload={user_id:session.user.id,name,active:true};if(kind==="areas"){existing=await existingArea(name)}else if(kind==="themes"){const areaId=document.querySelector("#newTaxArea").value;if(!areaId){msg.textContent="Escolhe a área.";return}payload.area_id=areaId;existing=await existingTheme(name,areaId)}else existing=await existingPerson(name);if(existing){if(existing.active){msg.textContent="Já existe "+(kind==="areas"?"uma área":kind==="themes"?"um tema":"uma pessoa")+" com esse nome.";return}msg.textContent="Já existe "+(kind==="areas"?"uma área":kind==="themes"?"um tema":"uma pessoa")+" com esse nome (está desativad"+(kind==="areas"?"a":"o")+").";saveBtn.style.display="none";wrap.innerHTML='<button class="btn" id="taxonomyReactivate">Reativar '+label+'</button>';document.querySelector("#taxonomyReactivate").onclick=async()=>{const btn=document.querySelector("#taxonomyReactivate");btn.disabled=true;btn.textContent="A reativar…";try{const table=kind==="areas"?"areas":kind==="themes"?"themes":"people";const{error}=await db.from(table).update({active:true}).eq("id",existing.id);if(error)throw error;await Promise.all([loadTaxonomy(),loadProcedures(),loadTags()]);await loadEntries();openTaxonomyManager(kind)}catch(err){btn.disabled=false;btn.textContent="Reativar "+label;msg.textContent="Erro: "+(err.message||"não foi possível reativar")}};return}const table=kind==="areas"?"areas":kind==="themes"?"themes":"people";const{error}=await db.from(table).insert(payload);if(error)throw error;await loadTaxonomy();openTaxonomyManager(kind)}catch(err){msg.textContent="Erro: "+(err.message||"não foi possível guardar")}}}
function editTaxonomy(kind,id){const list=kind==="areas"?areas:kind==="themes"?themes:people,item=list.find(x=>x.id===id);if(!item)return;const table=kind==="areas"?"areas":kind==="themes"?"themes":"people";sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div class="sheet-title">Editar '+(kind==="areas"?"área":kind==="themes"?"tema":"pessoa")+'</div><button class="close" id="x">×</button></div><div class="field"><label>Nome</label><input id="taxonomyName" value="'+esc(item.name)+'"></div><button class="btn" id="taxonomySave">Guardar alterações</button><button class="btn secondary" id="taxonomyDeactivate">Desativar</button><div class="muted small center-note" id="taxonomyMsg"></div></div>';document.querySelector("#x").onclick=()=>openTaxonomyManager(kind);document.querySelector("#taxonomySave").onclick=async()=>{const name=document.querySelector("#taxonomyName").value.trim(),msg=document.querySelector("#taxonomyMsg");if(!name)return;const duplicate=list.some(x=>x.id!==id&&x.name.trim().toLocaleLowerCase("pt-PT")===name.toLocaleLowerCase("pt-PT"));if(duplicate){msg.textContent="Já existe "+(kind==="areas"?"uma área":kind==="themes"?"um tema":"uma pessoa")+" com esse nome.";return}const{error}=await db.from(table).update({name}).eq("id",id);if(error){msg.textContent="Erro: "+error.message;return}await Promise.all([loadTaxonomy(),loadProcedures(),loadTags()]);await loadEntries();openTaxonomyManager(kind)};document.querySelector("#taxonomyDeactivate").onclick=async()=>{const msg=document.querySelector("#taxonomyMsg");msg.textContent="A verificar utilização…";try{const refs=await taxonomyReferences(kind,id);const total=refs.entries.length+refs.themes.length+refs.procedures.length+refs.answers.length;if(total){openTaxonomyReferences(kind,item,refs);return}const{error}=await db.from(table).update({active:false}).eq("id",id);if(error)throw error;await Promise.all([loadTaxonomy(),loadProcedures(),loadTags()]);await loadEntries();openTaxonomyManager(kind)}catch(err){msg.textContent="Erro: "+(err.message||"não foi possível verificar")}}}
async function taxonomyReferences(kind,id){const out={entries:[],themes:[],procedures:[],answers:[]};if(kind==="areas"){const[e,t,p]=await Promise.all([db.from("entries").select("id").eq("area_id",id).is("deleted_at",null),db.from("themes").select("id,name").eq("area_id",id).eq("active",true),db.from("procedures").select("id,title").eq("area_id",id).eq("active",true)]);if(e.error)throw e.error;if(t.error)throw t.error;if(p.error)throw p.error;out.entries=(e.data||[]).map(x=>x.id);out.themes=t.data||[];out.procedures=p.data||[]}else if(kind==="themes"){const[e,p]=await Promise.all([db.from("entries").select("id").eq("theme_id",id).is("deleted_at",null),db.from("procedures").select("id,title").eq("theme_id",id).eq("active",true)]);if(e.error)throw e.error;if(p.error)throw p.error;out.entries=(e.data||[]).map(x=>x.id);out.procedures=p.data||[]}else{const[e,a]=await Promise.all([db.from("entries").select("id").eq("person_id",id).is("deleted_at",null),db.from("entries").select("id").eq("answered_by_id",id).is("deleted_at",null)]);if(e.error)throw e.error;if(a.error)throw a.error;out.entries=(e.data||[]).map(x=>x.id);out.answers=(a.data||[]).map(x=>x.id)}return out}
function openTaxonomyReferences(kind,item,refs){const linkedEntries=[...new Set([...refs.entries,...refs.answers])].map(id=>entries.find(e=>String(e.id)===String(id))).filter(Boolean);const groups=[];if(linkedEntries.length)groups.push('<div class="eyebrow">CADERNO</div>'+linkedEntries.map(e=>'<button class="recent-item recent-button" data-ref-entry="'+e.id+'"><div class="item-icon">'+e.icon+'</div><div class="item-main"><div class="item-title">'+esc(e.title)+'</div><div class="item-meta">'+esc(e.meta)+'</div></div><div class="chev">›</div></button>').join(""));if(refs.themes.length)groups.push('<div class="eyebrow">TEMAS</div>'+refs.themes.map(t=>'<button class="recent-item recent-button" data-ref-theme="'+t.id+'"><div class="item-icon">🏷️</div><div class="item-main"><div class="item-title">'+esc(t.name)+'</div></div><div class="chev">›</div></button>').join(""));if(refs.procedures.length)groups.push('<div class="eyebrow">PROCEDIMENTOS</div>'+refs.procedures.map(p=>'<button class="recent-item recent-button" data-ref-procedure="'+p.id+'"><div class="item-icon">📚</div><div class="item-main"><div class="item-title">'+esc(p.title)+'</div></div><div class="chev">›</div></button>').join(""));sheet.innerHTML='<div class="sheet-panel"><div class="sheet-handle"></div><div class="row"><div><div class="eyebrow">EM UTILIZAÇÃO</div><div class="sheet-title">Não é possível desativar</div></div><button class="close" id="x">×</button></div><div class="muted">“'+esc(item.name)+'” ainda está associado a estes registos. Abre os que estiverem mal categorizados e altera primeiro a associação.</div><div class="card taxonomy-ref-list">'+groups.join("")+'</div></div>';document.querySelector("#x").onclick=()=>editTaxonomy(kind,item.id);document.querySelectorAll("[data-ref-entry]").forEach(b=>b.onclick=()=>openEntry(b.dataset.refEntry));document.querySelectorAll("[data-ref-theme]").forEach(b=>b.onclick=()=>editTaxonomy("themes",b.dataset.refTheme));document.querySelectorAll("[data-ref-procedure]").forEach(b=>b.onclick=()=>openProcedure(b.dataset.refProcedure))}
document.querySelector("#menuBtn").onclick=openMenu;

(async()=>{const{data}=await db.auth.getSession();session=data.session;if(!session){loginScreen();return}document.querySelector("header").style.display="";document.querySelector("nav").style.display="";await Promise.all([loadTaxonomy(),loadProcedures(),loadTags()]);await loadEntries();await loadAttachmentIndicators();render()})();